PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS groups (id TEXT PRIMARY KEY, name TEXT NOT NULL CHECK(length(name)<=80), created_by TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS memberships (group_id TEXT NOT NULL REFERENCES groups(id) ON DELETE CASCADE, user_email TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('owner','member')), joined_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(group_id,user_email));
CREATE TABLE IF NOT EXISTS invitations (id TEXT PRIMARY KEY, group_id TEXT NOT NULL REFERENCES groups(id) ON DELETE CASCADE, email TEXT NOT NULL, token_hash TEXT NOT NULL UNIQUE, created_by TEXT NOT NULL, expires_at TEXT NOT NULL, accepted_at TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS posts (id TEXT PRIMARY KEY, group_id TEXT NOT NULL REFERENCES groups(id) ON DELETE CASCADE, author_email TEXT NOT NULL, kanji TEXT NOT NULL CHECK(length(kanji)<=80), kana TEXT NOT NULL CHECK(length(kana)<=120), meaning TEXT NOT NULL CHECK(length(meaning)<=200), note TEXT NOT NULL DEFAULT '' CHECK(length(note)<=240), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS posts_group_created ON posts(group_id,created_at DESC);
CREATE TABLE IF NOT EXISTS comments (id TEXT PRIMARY KEY, post_id TEXT NOT NULL REFERENCES posts(id) ON DELETE CASCADE, group_id TEXT NOT NULL REFERENCES groups(id) ON DELETE CASCADE, author_email TEXT NOT NULL, body TEXT NOT NULL CHECK(length(body) BETWEEN 1 AND 240), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS progress_snapshots (group_id TEXT NOT NULL REFERENCES groups(id) ON DELETE CASCADE, user_email TEXT NOT NULL, username TEXT NOT NULL, level INTEGER NOT NULL, radicals INTEGER, kanji INTEGER, vocabulary INTEGER, radicals_total INTEGER, kanji_total INTEGER, vocabulary_total INTEGER, published_level INTEGER NOT NULL DEFAULT 0, published_counts INTEGER NOT NULL DEFAULT 0, synced_at TEXT NOT NULL, PRIMARY KEY(group_id,user_email));
CREATE TABLE IF NOT EXISTS privacy_settings (group_id TEXT NOT NULL, user_email TEXT NOT NULL, publish_level INTEGER NOT NULL DEFAULT 0, publish_counts INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(group_id,user_email), FOREIGN KEY(group_id,user_email) REFERENCES memberships(group_id,user_email) ON DELETE CASCADE);

CREATE TABLE IF NOT EXISTS api_write_limits (user_email TEXT NOT NULL, minute INTEGER NOT NULL, hits INTEGER NOT NULL, PRIMARY KEY(user_email,minute));
